/*
 * A059262  Primes p such that x^9 = 2 has no solution mod p.
 * https://oeis.org/A059262
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   a(n) is the nth prime p for which the congruence x^9 ≡ 2 has no
 *            solution mod p. The sequence is generated by checking
 *            consecutive primes and selecting those that fail the residue
 *            test
 * Range:     u8 n <= 19, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Validated: standard, pass, 70 terms through n = 978 (2026-11-03)
 * Helpers:   gcd, is_prime, mem, powmod
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include "../utils/gcd.h"
#include "../utils/is_prime.h"
#include "../utils/powmod.h"
#include "../utils/mem.h"

seq_t a(idx_t n)
{
    static seq_t *seq = NULL;
    static size_t seq_len = 0, seq_cap = 0;
    static idx_t candidate = 3;     /* first odd > 2 */

    /* Ensure we have at least n terms computed. */
    while (seq_len < (size_t)n)
    {
        /* Grow storage if needed. */
        if (seq == NULL)
        {
            seq_cap = 10;
            seq = mem_new(seq_t, seq_cap);
            if (seq == NULL) return 0; /* allocation failed */
        }
        else if (seq_len == seq_cap)
        {
            seq_cap <<= 1;
            seq = mem_resize(seq_t, seq, seq_cap);
            if (seq == NULL) return 0; /* allocation failed */
        }

        /* Find next prime candidate. */
        while (!is_prime(candidate))
        {
            candidate += 2;              /* skip even numbers */
        }
        uint64_t p = candidate;
        candidate += 2;                  /* next odd candidate for subsequent loop */

        /* Test whether 2 is a ninth power residue modulo p. */
        seq_t d   = gcd((seq_t)9, (seq_t)(p - 1));
        seq_t exp = (seq_t)(p - 1) / d;
        seq_t r   = powmod((seq_t)2, (uint64_t)exp, (seq_t)p);

        if (r != (seq_t)1)
        {
            seq[seq_len++] = (seq_t)p;   /* append p to the sequence */
        }
    }

    return seq[n - 1];
}
